/* every icon song becomes a playable song page */
(()=>{for(const inst in ICONS){if(!PLAYDB[inst])continue;ICONS[inst].forEach(ic=>{let L=PLAYDB[inst].find(x=>x.name===ic.name);if(!L){L={genre:ic.genre,name:ic.name,blurb:ic.blurb,songs:[]};PLAYDB[inst].push(L)}
 const norm=t=>t.toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9']+/g,' ').trim();
 ic.eras.forEach(e=>e.songs.forEach(([t,y,ks,note])=>{const ok=ks.filter(k=>TECH[inst][k]);if(!ok.length)return;const ex=L.songs.find(s=>norm(s[0])===norm(t));if(ex){if(Array.isArray(ex[1])&&!String(ex[1][0]).startsWith('pd:'))ok.forEach(k=>{if(!ex[1].includes(k)&&ex[1].length<5)ex[1].push(k)})}else L.songs.push([t,ok.slice(0,5),note])}))})}})();
